#include "luci.h"
#include <freetype/ft2build.h>
#include FT_FREETYPE_H

static LUCI_Font font_from_face(FT_Face face, unsigned int size) {
    LUCI_Font result = {0};
    if (!face) return result;

    FT_Set_Pixel_Sizes(face, 0, size);

    int ascent = (int)(face->size->metrics.ascender >> 6);
    int line_height = (int)(face->size->metrics.height >> 6);
    size_t num_glyphs = 95;

    LUCI_Glyph* glyphs = calloc(num_glyphs, sizeof(LUCI_Glyph));
    if (!glyphs) return result;

    int atlas_width = 512;
    int pen_x = 0, pen_y = 0, row_height = 0;
    int load_flags = FT_LOAD_RENDER;

    // 1. Measurement pass
    for (size_t i = 0; i < num_glyphs; i++) {
        uint32_t code = 32 + (uint32_t)i;
        if (FT_Load_Char(face, code, load_flags)) continue;

        int g_w = (int)face->glyph->bitmap.width;
        int g_h = (int)face->glyph->bitmap.rows;

        if (pen_x + g_w + 1 > atlas_width) {
            pen_x = 0;
            pen_y += row_height + 1;
            row_height = 0;
        }
        if (g_h > row_height) row_height = g_h;
        pen_x += g_w + 1;
    }

    int atlas_height = pen_y + row_height + 1;
    int h = 512;
    while (h < atlas_height) h *= 2;
    atlas_height = h;

    unsigned char* atlas_data = calloc((size_t)atlas_width * atlas_height, 1);
    unsigned char* rgba_data = calloc((size_t)atlas_width * atlas_height * 4, 1);
    if (!atlas_data || !rgba_data) {
        free(glyphs);
        free(atlas_data);
        free(rgba_data);
        return result;
    }

    // 2. Rasterization and packing pass
    pen_x = 0; pen_y = 0; row_height = 0;
    for (size_t i = 0; i < num_glyphs; i++) {
        uint32_t code = 32 + (uint32_t)i;
        
        if (FT_Load_Char(face, code, load_flags)) {
            glyphs[i] = (LUCI_Glyph){ .code = code };
            continue;
        }

        FT_Bitmap* bmp = &face->glyph->bitmap;
        int g_w = (int)bmp->width;
        int g_h = (int)bmp->rows;

        if (pen_x + g_w + 1 > atlas_width) {
            pen_x = 0;
            pen_y += row_height + 1;
            row_height = 0;
        }
        if (g_h > row_height) row_height = g_h;

        // Copy bitmap buffer into atlas data
        for (int y = 0; y < g_h; y++) {
            for (int x = 0; x < g_w; x++) {
                atlas_data[(size_t)(pen_y + y) * atlas_width + (pen_x + x)] = bmp->buffer[y * bmp->pitch + x];
            }
        }

        // Store glyph metrics (with direct Y inversion calculation)
        glyphs[i] = (LUCI_Glyph){
            .code = code,
            .x = pen_x,
            .y = atlas_height - pen_y - g_h,
            .w = g_w,
            .h = g_h,
            .bearing_x = face->glyph->bitmap_left,
            .bearing_y = face->glyph->bitmap_top,
            .advance = (float)face->glyph->advance.x / 64.0f
        };

        pen_x += g_w + 1;
    }

    // 3. Swizzle single-channel bitmap to RGBA with vertical flip for UV coordinates
    for (int y = 0; y < atlas_height; y++) {
        int src_row = (atlas_height - 1 - y) * atlas_width;
        int dst_row = y * atlas_width * 4;

        for (int x = 0; x < atlas_width; x++) {
            unsigned char alpha = atlas_data[src_row + x];
            unsigned char* pixel = &rgba_data[dst_row + x * 4];
            pixel[0] = 255;   // Red
            pixel[1] = 255;   // Green
            pixel[2] = 255;   // Blue
            pixel[3] = alpha; // Alpha
        }
    }

    result.texture = LUCI_create_texture(rgba_data, atlas_width, atlas_height, 4);
    result.glyphs = glyphs;
    result.length = num_glyphs;
    result.ascent = ascent;
    result.line_height = line_height;
    result.font_size = size;

    free(rgba_data);
    free(atlas_data);
    return result;
}

 // Load font from raw memory buffer.
LUCI_Font load_font_from_memory(const unsigned char* data, size_t data_size, unsigned int size) {
    FT_Library ft = NULL;
    FT_Face face = NULL;
    LUCI_Font result = {0};

    if (FT_Init_FreeType(&ft)) {
        fprintf(stderr, "ERROR::FREETYPE: Could not init FreeType Library\n");
        return result;
    }

    if (FT_New_Memory_Face(ft, data, (FT_Long)data_size, 0, &face)) {
        fprintf(stderr, "ERROR::FREETYPE: Failed to load font from memory\n");
        FT_Done_FreeType(ft);
        return result;
    }

    result = font_from_face(face, size);

    FT_Done_Face(face);
    FT_Done_FreeType(ft);

    return result;
}

// Load font from a file path on disk.
LUCI_Font load_font(const char* path, unsigned int size) {
    FT_Library ft = NULL;
    FT_Face face = NULL;
    LUCI_Font result = {0};

    if (FT_Init_FreeType(&ft)) {
        fprintf(stderr, "ERROR::FREETYPE: Could not init FreeType Library\n");
        return result;
    }

    if (FT_New_Face(ft, path, 0, &face)) {
        fprintf(stderr, "ERROR::FREETYPE: Failed to load font: %s\n", path);
        FT_Done_FreeType(ft);
        return result;
    }

    result = font_from_face(face, size);

    FT_Done_Face(face);
    FT_Done_FreeType(ft);

    return result;
}

